Select Likert Items

likert_items &lt;- data |&gt;
  select(pe1, pe2, pe3, pe4)

Long Format

likert_long &lt;- likert_items |&gt;
  pivot_longer(
    cols = everything(),
    names_to = "item",
    values_to = "response"
  ) |&gt;
  mutate(
    response = factor(
      response,
      levels = 1:5,
      labels = c(
        "Strongly disagree",
        "Disagree",
        "Neutral",
        "Agree",
        "Strongly agree"
      )
    )
  )

Add Residuals and Fitted Values

diagnostic_data &lt;- reg_data |&gt;
  mutate(
    fitted_values = fitted(model_reg),
    residuals = residuals(model_reg)
  )

Export Regression Table

reg_table |&gt;
  as_gt() |&gt;
  gt::gtsave("output/module4_regression_table.html")

Import Data

dirty_data &lt;- read_excel(
  "data/FPT_PolySchool_R_Training_Demo_Dataset.xlsx",
  sheet = "02_Dirty_Data"
) |&gt;
  clean_names()

Missing Percentage

missing_report &lt;- tibble(
  variable = names(dirty_data),
  missing_n = colSums(is.na(dirty_data))
) |&gt;
  mutate(
    missing_pct = round(
      missing_n / nrow(dirty_data) * 100,
      2
    )
  )

missing_report

View Duplicate Records

dirty_data |&gt;
  filter(duplicated(id) | duplicated(id, fromLast = TRUE)) |&gt;
  arrange(id)

Remove Duplicates

clean_data &lt;- dirty_data |&gt;
  distinct(id, .keep_all = TRUE)

Check Data Types

clean_data |&gt;
  select(all_of(likert_vars)) |&gt;
  summarise(
    across(
      everything(),
      ~ class(.)[1]
    )
  )

Convert Likert Variables to Numeric

clean_data &lt;- clean_data |&gt;
  mutate(
    across(
      all_of(likert_vars),
      ~ as.numeric(.)
    )
  )

Nếu R báo cảnh báo NAs introduced by coercion, điều đó có nghĩa là một số giá trị chữ hoặc lỗi đã được chuyển thành NA.

Detect Invalid Values

invalid_likert_report &lt;- clean_data |&gt;
  summarise(
    across(
      all_of(likert_vars),
      ~ sum(!(. %in% 1:5), na.rm = TRUE)
    )
  )

invalid_likert_report

Convert Invalid Values to NA

clean_data &lt;- clean_data |&gt;
  mutate(
    across(
      all_of(likert_vars),
      ~ ifelse(. %in% 1:5, ., NA)
    )
  )

Mean Imputation for Likert Variables

clean_data &lt;- clean_data |&gt;
  mutate(
    across(
      all_of(likert_vars),
      ~ replace_na(., mean(., na.rm = TRUE))
    )
  )

Remaining Missing Values

clean_data |&gt;
  summarise(
    across(
      everything(),
      ~ sum(is.na(.))
    )
  )

