Import Likert Data

likert_data &lt;- read_excel(
  advanced_file,
  sheet = "07_Likert_Advanced"
) |&gt;
  clean_names()

Long Format

likert_long &lt;- likert_data |&gt;
  pivot_longer(
    cols = starts_with("q"),
    names_to = "item",
    values_to = "response"
  ) |&gt;
  mutate(
    response = factor(
      response,
      levels = 1:5,
      labels = c(
        "Strongly disagree",
        "Disagree",
        "Neutral",
        "Agree",
        "Strongly agree"
      )
    )
  )

Horizontal Stacked Likert Bar

likert_summary &lt;- likert_long |&gt;
  count(item, response) |&gt;
  group_by(item) |&gt;
  mutate(percent = n / sum(n) * 100) |&gt;
  ungroup()

ggplot(likert_summary, aes(x = percent, y = item, fill = response)) +
  geom_col() +
  labs(
    title = "Horizontal Likert-style Stacked Bar",
    x = "Percent",
    y = "Survey item",
    fill = "Response"
  ) +
  theme_minimal()

