7.9.12 Line Chart

adv_desc |&gt;
  mutate(date = as.Date(date)) |&gt;
  group_by(date) |&gt;
  summarise(
    mean_satisfaction = mean(satisfaction, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  ggplot(aes(x = date, y = mean_satisfaction)) +
  geom_line() +
  labs(
    title = "Line Chart",
    x = "Date",
    y = "Mean satisfaction"
  ) +
  theme_minimal()

7.9.13 Area Chart

adv_desc |&gt;
  mutate(date = as.Date(date)) |&gt;
  group_by(date) |&gt;
  summarise(
    claims = sum(claims_count, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  ggplot(aes(x = date, y = claims)) +
  geom_area(alpha = 0.6) +
  labs(
    title = "Area Chart",
    x = "Date",
    y = "Claims"
  ) +
  theme_minimal()

7.9.15 Mean and Error Bar Plot

adv_desc |&gt;
  group_by(region) |&gt;
  summarise(
    mean_satisfaction = mean(satisfaction, na.rm = TRUE),
    se_satisfaction = sd(satisfaction, na.rm = TRUE) / sqrt(n()),
    .groups = "drop"
  ) |&gt;
  ggplot(aes(x = region, y = mean_satisfaction)) +
  geom_col() +
  geom_errorbar(
    aes(
      ymin = mean_satisfaction - se_satisfaction,
      ymax = mean_satisfaction + se_satisfaction
    ),
    width = 0.2
  ) +
  labs(
    title = "Mean Plot with Standard Error",
    x = "Region",
    y = "Mean satisfaction"
  ) +
  theme_minimal()

7.9.16 Dot Plot

adv_desc |&gt;
  group_by(school) |&gt;
  summarise(
    mean_gpa = mean(gpa, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  ggplot(aes(x = mean_gpa, y = reorder(school, mean_gpa))) +
  geom_point(size = 3) +
  labs(
    title = "Dot Plot",
    x = "Mean GPA",
    y = "School"
  ) +
  theme_minimal()

7.9.17 Lollipop Chart

adv_desc |&gt;
  group_by(school) |&gt;
  summarise(
    mean_satisfaction = mean(satisfaction, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  ggplot(aes(x = mean_satisfaction, y = reorder(school, mean_satisfaction))) +
  geom_segment(aes(x = 0, xend = mean_satisfaction, yend = school)) +
  geom_point(size = 3) +
  labs(
    title = "Lollipop Chart",
    x = "Mean satisfaction",
    y = "School"
  ) +
  theme_minimal()
